#include <bits/stdc++.h>
using namespace std;

const long long MOD = 998244353;

long long fact(int n) {
    long long res = 1;
    for (int i = 2; i <= n; i++) {
        res = (res * i) % MOD;
    }
    return res;
}

long long modInverse(long long a, long long m) {
    long long m0 = m, t, q;
    long long x0 = 0, x1 = 1;
    if (m == 1) return 0;
    while (a > 1) {
        q = a / m;
        t = m;
        m = a % m; a = t;
        t = x0;
        x0 = x1 - q * x0;
        x1 = t;
    }
    if (x1 < 0) x1 += m0;
    return x1;
}

long long nCr(int n, int r) {
    if (r < 0 || r > n) return 0;
    long long numerator = fact(n);
    long long denominator = (fact(r) * fact(n - r)) % MOD;
    return (numerator * modInverse(denominator, MOD)) % MOD;
}

long long pow_mod(long long base, int exp) {
    long long result = 1;
    long long b = base % MOD;
    int e = exp;
    while (e > 0) {
        if (e & 1) result = (result * b) % MOD;
        b = (b * b) % MOD;
        e >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    long long k;
    cin >> n >> k;

    if (k == 0) {
        cout << fact(n) % MOD << "\n";
        return 0;
    }
    if (k > n - 1) {
        cout << 0 << "\n";
        return 0;
    }

    int c = n - (int)k;
    long long total = 0;

    for (int i = 1; i <= c; i++) {
        long long sign = ((c - i) % 2 == 0) ? 1 : -1;
        long long comb = nCr(c, i);
        long long power = pow_mod(i, n);
        total += sign * comb * power;
    }

    total *= 2 * nCr(n, c);
    total %= MOD;
    cout << total << "\n";

    return 0;
}
